INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-203', 'formula', 'problem-solving', 'Median of a data set', NULL, 'Arrange the values and take the middle one; with an even count, average the two middle values.', '\text{middle value in order}', ARRAY['problem-solving', 'statistics']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-204', 'formula', 'problem-solving', 'Mode', NULL, 'A data set can have no mode, one mode, or several.', '\text{most frequent value}', ARRAY['problem-solving', 'statistics']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-205', 'formula', 'problem-solving', 'Range of a data set', NULL, 'A rough spread measure; one outlier can dominate it.', '\text{range}=\text{max}-\text{min}', ARRAY['problem-solving', 'statistics']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-193', 'formula', 'formula', 'Weighted mean', NULL, 'Multiply by weights before summing.', '\bar{x}_w=\dfrac{\sum w_i x_i}{\sum w_i}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-206', 'formula', 'problem-solving', 'Probability of an event', NULL, 'Every outcome must be equally likely for this ratio to apply.', 'P(E)=\dfrac{\text{favorable outcomes}}{\text{total equally likely outcomes}}', ARRAY['problem-solving', 'probability']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-170', 'formula', 'formula', 'Complement rule', NULL, 'Something or nothing.', 'P(\text{not }A)=1-P(A)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-207', 'formula', 'problem-solving', 'Independent events', NULL, 'Multiply only when one event does not change the other''s probability.', 'P(A\text{ and }B)=P(A)\,P(B)', ARRAY['problem-solving', 'probability']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-208', 'formula', 'algebra', 'Slope of a perpendicular line', NULL, 'Perpendicular slopes are negative reciprocals; a horizontal line pairs with a vertical one.', 'm_\perp=-\dfrac{1}{m}', ARRAY['algebra', 'geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-103', 'formula', 'formula', 'Parallel lines', NULL, 'Parallel lines share slopes.', 'm_1=m_2', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-105', 'formula', 'formula', 'Midpoint formula', NULL, 'Average the coordinates for the midpoint.', '\left(\dfrac{x_1+x_2}{2},\dfrac{y_1+y_2}{2}\right)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-106', 'formula', 'formula', 'Distance formula', NULL, 'Pythagoras between two points.', 'd=\sqrt{(x_2-x_1)^2+(y_2-y_1)^2}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-102', 'formula', 'formula', 'Point-slope form', NULL, 'Line of slope m through (x1, y1).', 'y-y_1=m(x-x_1)', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-209', 'formula', 'algebra', 'Standard form of a line', NULL, 'Solve for y to read the slope and intercept; the intercepts are C/A and C/B.', 'Ax+By=C', ARRAY['algebra']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-210', 'formula', 'algebra', 'System with no solution', NULL, 'Parallel lines never intersect, so there is no pair (x, y) that satisfies both.', '\text{same slope, different intercept}', ARRAY['algebra']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-211', 'formula', 'algebra', 'System with infinitely many solutions', NULL, 'The two equations describe one line, so every point on it works.', '\text{same line after simplifying}', ARRAY['algebra']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-212', 'formula', 'advanced-math', 'Vertex form of a quadratic', NULL, 'The vertex is (h, k); the sign of a gives the direction of opening.', 'y=a(x-h)^2+k', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-213', 'formula', 'advanced-math', 'Discriminant', NULL, 'Positive: two real roots. Zero: one repeated root. Negative: no real roots.', 'b^2-4ac', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-214', 'formula', 'advanced-math', 'Sum and product of roots', NULL, 'Useful when the roots are awkward to compute directly.', 'r_1+r_2=-\dfrac{b}{a},\qquad r_1r_2=\dfrac{c}{a}', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-215', 'formula', 'advanced-math', 'Function notation', NULL, 'f(3) means substitute 3 for every x, not multiply f by 3.', 'f(x)=\text{output for input }x', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-216', 'formula', 'advanced-math', 'Transformations of f(x)', NULL, 'h shifts right, k shifts up, the minus signs reflect, a stretches or compresses vertically.', 'f(x-h)+k,\ -f(x),\ f(-x),\ af(x)', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-217', 'formula', 'advanced-math', 'Inverse variation', NULL, 'As x grows, y shrinks; the product xy stays constant.', 'y=\dfrac{k}{x}', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-218', 'formula', 'advanced-math', 'Direct variation', NULL, 'The ratio y/x is constant; the graph is a line through the origin.', 'y=kx', ARRAY['advanced-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-175', 'formula', 'formula', 'Arithmetic sequence', NULL, 'nth term of an arithmetic sequence.', 'a_n=a_1+(n-1)d', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-177', 'formula', 'formula', 'Geometric sequence', NULL, 'nth term with ratio r.', 'a_n=a_1 r^{n-1}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-219', 'formula', 'problem-solving', 'Exponential growth vs linear growth', NULL, 'Exponential multiplies by a constant factor per step; linear adds a constant amount.', 'y=ab^x \ \text{vs}\ y=mx+b', ARRAY['problem-solving']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-220', 'formula', 'problem-solving', 'Interpreting a linear model', NULL, 'b is the starting value; m is the change per unit of x, with its units.', 'y=mx+b', ARRAY['problem-solving']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-221', 'formula', 'problem-solving', 'Density', NULL, 'Rearrange for mass or volume; keep units consistent.', '\text{density}=\dfrac{\text{mass}}{\text{volume}}', ARRAY['problem-solving']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-152', 'formula', 'formula', 'Unit rate', NULL, 'Divide to find a per-unit value.', '\text{rate}=\dfrac{\text{total}}{\text{units}}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-222', 'formula', 'geometry', 'Similar triangles', NULL, 'Corresponding sides are proportional and corresponding angles are equal.', '\dfrac{a}{a''}=\dfrac{b}{b''}=\dfrac{c}{c''}', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-223', 'formula', 'geometry', 'Interior angles of a polygon', NULL, 'n is the number of sides; a regular polygon divides this equally.', '(n-2)\times180^\circ', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-224', 'formula', 'geometry', 'Exterior angle of a triangle', NULL, 'A quick route when the third angle is not needed.', '\text{exterior}=\text{sum of the two remote interior angles}', ARRAY['geometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-225', 'formula', 'geometry', 'Arc length in radians', NULL, 'Theta must be in radians; convert degrees first.', 's=r\theta', ARRAY['geometry', 'trigonometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-226', 'formula', 'trigonometry', 'Radian conversion', NULL, 'Multiply degrees by pi/180, or radians by 180/pi.', '180^\circ=\pi\ \text{radians}', ARRAY['trigonometry']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-227', 'formula', 'problem-solving', 'Line of best fit', NULL, 'It estimates the pattern, not a guarantee; predictions far outside the data are unreliable.', '\text{prediction from a trend line}', ARRAY['problem-solving', 'statistics']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-165', 'formula', 'formula', 'Margin of error', NULL, 'Confidence interval width.', '\pm z\sqrt{\dfrac{\hat p(1-\hat p)}{n}}', ARRAY['formula', 'sat-math']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
INSERT INTO public.flashcards (id, deck_type, category, front_prompt, part_of_speech, back_definition, example_or_application, synonyms_or_related, source_attribution) VALUES ('F-228', 'formula', 'problem-solving', 'Correlation and causation', NULL, 'A third variable can drive both, so an observed relationship alone does not prove cause.', '\text{association}\not\Rightarrow\text{cause}', ARRAY['problem-solving', 'statistics']::TEXT[], 'HDSAT Study Deck (CC-BY-4.0)') ON CONFLICT (id) DO UPDATE SET deck_type = EXCLUDED.deck_type, category = EXCLUDED.category, front_prompt = EXCLUDED.front_prompt, back_definition = EXCLUDED.back_definition, example_or_application = EXCLUDED.example_or_application, synonyms_or_related = EXCLUDED.synonyms_or_related;
